'use client';

import { useMemo, useState } from 'react';
import { Building2, FileText, FolderCheck, KeyRound, LogOut, Plus, Save, ShieldCheck, Trash2, UploadCloud, UserRound, UsersRound } from 'lucide-react';

type Role = 'Agremiado' | 'Líder' | 'Administrativo';
type DocState = 'Pendiente' | 'Cargado' | 'Aprobado' | 'Rechazado' | 'Por vencer';
type DocItem = { id: string; name: string; state: DocState; fileName?: string; comment?: string; vencimiento?: string };
type Institution = { id: string; name: string; nit: string; city: string; areas: string[] };
type Person = { id: string; name: string; email: string; role: Role; institutionId?: string; area?: string; perfil?: 'Asistencial' | 'Administrativo' };

const asistencialDocs = [
  'Cédula de ciudadanía al 150% a color','Foto carnet fondo blanco','Libreta militar o constancia','Hoja de vida función pública diligenciada y firmada','Diplomas académicos','Actas de grado','Resolución de convalidación si aplica','Tarjeta profesional','RETHUS actualizado','Póliza de responsabilidad civil vigente','Cursos obligatorios y certificaciones del cargo','RUT actualizado','Declaración juramentada de bienes y rentas','Antecedentes judiciales','Antecedentes fiscales','Antecedentes disciplinarios','Medidas correctivas','Inhabilidades delitos sexuales','REDAM','Certificaciones laborales mínimo 2','Retención en la fuente','Uso adecuado de recursos institucionales','Tratamiento de datos personales','Confidencialidad y no divulgación','Dependiente económico','Carnet de vacunas','Examen médico laboral','Certificación bancaria','Certificación EPS','Fondo de pensiones','Certificación ARL','Caja de compensación'
];
const administrativoDocs = [
  'Cédula de ciudadanía al 150% a color','Foto carnet fondo blanco','Libreta militar o constancia','Hoja de vida función pública diligenciada y firmada','Diplomas académicos','Actas de grado','Tarjeta profesional','RUT actualizado','Declaración juramentada de bienes y rentas','Antecedentes judiciales','Antecedentes fiscales','Antecedentes disciplinarios','Medidas correctivas','Inhabilidades delitos sexuales','REDAM','Certificaciones laborales mínimo 2','Retención en la fuente','Uso adecuado de recursos institucionales','Tratamiento de datos personales','Confidencialidad y no divulgación','Dependiente económico','Carnet de vacunas','Examen médico laboral','Certificación bancaria','Certificación EPS','Fondo de pensiones','Certificación ARL','Caja de compensación'
];

const uid = () => Math.random().toString(36).slice(2, 9);

export default function Page() {
  const [screen, setScreen] = useState<'login'|'register'|'portal'>('login');
  const [user, setUser] = useState<Person | null>(null);
  const [role, setRole] = useState<Role>('Agremiado');
  const [perfil, setPerfil] = useState<'Asistencial'|'Administrativo'>('Asistencial');
  const [active, setActive] = useState('vinculacion');
  const [docs, setDocs] = useState<DocItem[]>(asistencialDocs.map((name, i) => ({ id: `doc-${i+1}`, name, state: 'Pendiente' })));
  const [institutions, setInstitutions] = useState<Institution[]>([
    { id: 'i1', name: 'Hospital Gonzalo Contreras E.S.E.', nit: '764000165501', city: 'La Unión, Valle', areas: ['Urgencias', 'Hospitalización', 'Consulta externa', 'Administrativa'] },
    { id: 'i2', name: 'Hospital Sagrada Familia E.S.E.', nit: '891900367', city: 'Toro, Valle', areas: ['Facturación', 'Enfermería', 'Laboratorio'] }
  ]);
  const [people, setPeople] = useState<Person[]>([
    { id: 'p1', name: 'Laura Medina', email: 'laura@agreserge.com', role: 'Líder', institutionId: 'i1', area: 'Urgencias' },
    { id: 'p2', name: 'Carlos Ramírez', email: 'carlos@agreserge.com', role: 'Agremiado', institutionId: 'i1', area: 'Hospitalización', perfil: 'Asistencial' }
  ]);
  const [ficha, setFicha] = useState({ nombres: '', documento: '', telefono: '', direccion: '', profesion: '', eps: '', banco: '', cuenta: '' });
  const [passwords, setPasswords] = useState({ actual: '', nueva: '', confirmar: '' });
  const [instForm, setInstForm] = useState({ name: '', nit: '', city: '', area: '' });
  const [personForm, setPersonForm] = useState({ name: '', email: '', role: 'Agremiado' as Role, institutionId: 'i1', area: '', perfil: 'Asistencial' as 'Asistencial'|'Administrativo' });

  const percent = useMemo(() => Math.round((docs.filter(d => d.state !== 'Pendiente').length / docs.length) * 100), [docs]);
  const currentDocs = perfil === 'Asistencial' ? asistencialDocs : administrativoDocs;

  function startSession() {
    const u = { id: uid(), name: role === 'Agremiado' ? 'Agremiado Demo' : role === 'Líder' ? 'Líder Demo' : 'Administrador AGRESERGE', email: 'usuario@agreserge.com', role, perfil } as Person;
    setUser(u);
    setScreen('portal');
    setDocs(currentDocs.map((name, i) => ({ id: `doc-${i+1}`, name, state: 'Pendiente' })));
    setActive(role === 'Agremiado' ? 'vinculacion' : 'admin');
  }
  function registerUser() {
    const u = { id: uid(), name: 'Nuevo usuario registrado', email: 'nuevo@agreserge.com', role, perfil } as Person;
    setPeople([...people, u]); setUser(u); setScreen('portal'); setActive('vinculacion');
  }
  function uploadDoc(id: string, file?: File) { if (!file) return; setDocs(docs.map(d => d.id === id ? { ...d, state: 'Cargado', fileName: file.name, comment: 'Documento cargado para revisión.' } : d)); }
  function deleteDoc(id: string) { setDocs(docs.map(d => d.id === id ? { ...d, state: 'Pendiente', fileName: undefined, comment: undefined, vencimiento: undefined } : d)); }
  function addInstitution() { if (!instForm.name.trim()) return; setInstitutions([...institutions, { id: uid(), name: instForm.name, nit: instForm.nit, city: instForm.city, areas: instForm.area ? [instForm.area] : [] }]); setInstForm({ name: '', nit: '', city: '', area: '' }); }
  function addArea(id: string, area: string) { if (!area.trim()) return; setInstitutions(institutions.map(i => i.id === id ? { ...i, areas: [...i.areas, area] } : i)); }
  function addPerson() { if (!personForm.name.trim() || !personForm.email.trim()) return; setPeople([...people, { id: uid(), ...personForm }]); setPersonForm({ name: '', email: '', role: 'Agremiado', institutionId: institutions[0]?.id || '', area: '', perfil: 'Asistencial' }); }
  function changePassword() { if (passwords.nueva && passwords.nueva === passwords.confirmar) { alert('Clave actualizada correctamente en el prototipo.'); setPasswords({ actual: '', nueva: '', confirmar: '' }); } else alert('La nueva clave y la confirmación no coinciden.'); }

  if (screen !== 'portal') return <main className="authPage"><section className="authCard">
    <div className="brand"><div className="brandIcon"><ShieldCheck size={30}/></div><div><h1>Intranet AGRESERGE</h1><p>Acceso institucional</p></div></div>
    <div className="authTabs"><button className={screen==='login'?'on':''} onClick={()=>setScreen('login')}>Iniciar sesión</button><button className={screen==='register'?'on':''} onClick={()=>setScreen('register')}>Registro</button></div>
    <div className="formGrid"><label>Perfil de acceso<select value={role} onChange={e=>setRole(e.target.value as Role)}><option>Agremiado</option><option>Líder</option><option>Administrativo</option></select></label>{screen==='register' && role==='Agremiado' && <label>Tipo de personal<select value={perfil} onChange={e=>setPerfil(e.target.value as any)}><option>Asistencial</option><option>Administrativo</option></select></label>}<label>Correo<input placeholder="correo@agreserge.com" /></label><label>Contraseña<input type="password" placeholder="********" /></label></div>
    <button className="primary" onClick={screen==='login'?startSession:registerUser}>{screen==='login'?'Ingresar a la intranet':'Registrar solicitud'}</button>
    <button className="ghost" onClick={()=>alert('Módulo de recuperación de contraseña listo para conectar con correo institucional.')}>Recuperar contraseña</button>
    <div className="roleStrip"><span>Agremiados</span><span>Líderes</span><span>Administrativos</span></div>
  </section></main>;

  return <main className="appShell">
    <aside className="sidebar"><div className="logoMini"><ShieldCheck/><div><b>Intranet AGRESERGE</b><small>{user?.role}</small></div></div><nav>
      {user?.role==='Agremiado' && <button className={active==='vinculacion'?'active':''} onClick={()=>setActive('vinculacion')}><FolderCheck/> Mi vinculación</button>}
      {(user?.role==='Líder' || user?.role==='Administrativo') && <button className={active==='admin'?'active':''} onClick={()=>setActive('admin')}><Building2/> Administración</button>}
      <button className={active==='clave'?'active':''} onClick={()=>setActive('clave')}><KeyRound/> Cambio de clave</button>
      <button onClick={()=>{setScreen('login'); setUser(null)}}><LogOut/> Salir</button>
    </nav></aside>
    <section className="content"><header className="topbar"><div><h2>{active==='vinculacion'?'Portal del agremiado':active==='admin'?'Panel administrativo':'Seguridad de la cuenta'}</h2><p>Sesión activa: {user?.name}</p></div><span className="pill">AGRESERGE DEL VALLE</span></header>
      {active==='vinculacion' && <AgremiadoPortal ficha={ficha} setFicha={setFicha} docs={docs} uploadDoc={uploadDoc} deleteDoc={deleteDoc} percent={percent} />}
      {active==='admin' && <AdminPanel institutions={institutions} instForm={instForm} setInstForm={setInstForm} addInstitution={addInstitution} addArea={addArea} people={people} personForm={personForm} setPersonForm={setPersonForm} addPerson={addPerson} setPeople={setPeople} />}
      {active==='clave' && <section className="panel narrow"><h3><KeyRound/> Cambio de clave</h3><p className="muted">Actualiza tu contraseña de ingreso a la intranet.</p><label>Clave actual<input type="password" value={passwords.actual} onChange={e=>setPasswords({...passwords, actual:e.target.value})}/></label><label>Nueva clave<input type="password" value={passwords.nueva} onChange={e=>setPasswords({...passwords, nueva:e.target.value})}/></label><label>Confirmar nueva clave<input type="password" value={passwords.confirmar} onChange={e=>setPasswords({...passwords, confirmar:e.target.value})}/></label><button className="primary" onClick={changePassword}>Actualizar clave</button></section>}
    </section>
  </main>;
}

function AgremiadoPortal({ ficha, setFicha, docs, uploadDoc, deleteDoc, percent }: any) { return <div className="gridTwo">
  <section className="panel"><h3><UserRound/> Ficha técnica de registro</h3><p className="muted">Información básica del agremiado para el proceso de vinculación.</p><div className="formGrid two">{Object.keys(ficha).map(k=><label key={k}>{label(k)}<input value={ficha[k]} onChange={e=>setFicha({...ficha,[k]:e.target.value})}/></label>)}</div><button className="primary"><Save/> Guardar ficha</button></section>
  <section className="panel"><h3><FolderCheck/> Cargue documental</h3><div className="progress"><span style={{width:`${percent}%`}}></span></div><p className="muted">Avance documental: <b>{percent}%</b></p><div className="docList">{docs.map((d:DocItem)=><div className="docRow" key={d.id}><div><b>{d.name}</b><small>{d.fileName || 'Sin archivo cargado'} · {d.state}</small></div><div className="actions"><label className="upload"><UploadCloud size={16}/> Cargar<input type="file" onChange={e=>uploadDoc(d.id, e.target.files?.[0])}/></label><button onClick={()=>deleteDoc(d.id)}><Trash2 size={16}/></button></div></div>)}</div></section>
</div> }
function AdminPanel(props:any) { const { institutions, instForm, setInstForm, addInstitution, addArea, people, personForm, setPersonForm, addPerson, setPeople } = props; return <div className="adminGrid">
  <section className="panel"><h3><Building2/> Instituciones</h3><div className="formGrid"><label>Nombre<input value={instForm.name} onChange={(e:any)=>setInstForm({...instForm,name:e.target.value})}/></label><label>NIT<input value={instForm.nit} onChange={(e:any)=>setInstForm({...instForm,nit:e.target.value})}/></label><label>Municipio<input value={instForm.city} onChange={(e:any)=>setInstForm({...instForm,city:e.target.value})}/></label><label>Área inicial<input value={instForm.area} onChange={(e:any)=>setInstForm({...instForm,area:e.target.value})}/></label></div><button className="primary" onClick={addInstitution}><Plus/> Cargar institución</button>{institutions.map((i:Institution)=><div className="miniCard" key={i.id}><b>{i.name}</b><small>NIT {i.nit} · {i.city}</small><div className="chips">{i.areas.map(a=><span key={a}>{a}</span>)}</div><AddArea onAdd={(a:string)=>addArea(i.id,a)}/></div>)}</section>
  <section className="panel"><h3><UsersRound/> Agremiados, líderes y administrativos</h3><div className="formGrid two"><label>Nombre<input value={personForm.name} onChange={(e:any)=>setPersonForm({...personForm,name:e.target.value})}/></label><label>Correo<input value={personForm.email} onChange={(e:any)=>setPersonForm({...personForm,email:e.target.value})}/></label><label>Perfil<select value={personForm.role} onChange={(e:any)=>setPersonForm({...personForm,role:e.target.value})}><option>Agremiado</option><option>Líder</option><option>Administrativo</option></select></label><label>Tipo documental<select value={personForm.perfil} onChange={(e:any)=>setPersonForm({...personForm,perfil:e.target.value})}><option>Asistencial</option><option>Administrativo</option></select></label><label>Institución<select value={personForm.institutionId} onChange={(e:any)=>setPersonForm({...personForm,institutionId:e.target.value})}>{institutions.map((i:Institution)=><option key={i.id} value={i.id}>{i.name}</option>)}</select></label><label>Área<input value={personForm.area} onChange={(e:any)=>setPersonForm({...personForm,area:e.target.value})}/></label></div><button className="primary" onClick={addPerson}><Plus/> Cargar usuario</button><div className="table">{people.map((p:Person)=><div className="tableRow" key={p.id}><span><b>{p.name}</b><small>{p.email}</small></span><span>{p.role}</span><span>{p.area || 'Sin área'}</span><button onClick={()=>setPeople(people.filter((x:Person)=>x.id!==p.id))}><Trash2 size={16}/></button></div>)}</div></section>
</div> }
function AddArea({onAdd}:any){const [v,setV]=useState(''); return <div className="addArea"><input placeholder="Nueva área" value={v} onChange={e=>setV(e.target.value)}/><button onClick={()=>{onAdd(v);setV('')}}>Agregar área</button></div>}
function label(k:string){return ({nombres:'Nombres completos',documento:'Documento',telefono:'Teléfono',direccion:'Dirección',profesion:'Profesión u oficio',eps:'EPS',banco:'Banco',cuenta:'Número de cuenta'} as any)[k] || k}
